#pragma once
#include <stdint.h>
#include <math.h>
#define STRIP_PALETTE_COUNT 11
// IDs are stable and shared with the portal. Original, cyclic RGB gradients.
static const uint8_t strip_palette_stops[STRIP_PALETTE_COUNT][6][3]={{{255,0,0},{255,255,0},{0,255,0},{0,255,255},{0,0,255},{255,0,255}},{{0,18,43},{0,60,128},{0,126,170},{0,219,196},{101,246,228},{0,108,143}},{{33,0,0},{168,0,0},{255,44,0},{255,134,0},{255,225,64},{255,237,176}},{{8,28,56},{0,94,83},{0,217,147},{132,242,149},{120,87,220},{32,48,154}},{{53,18,108},{161,27,130},{248,79,104},{255,147,69},{255,209,138},{112,66,167}},{{22,11,79},{72,33,183},{232,43,194},{255,71,134},{27,228,238},{8,104,212}},{{5,35,21},{18,104,57},{72,166,55},{197,207,72},{72,150,107},{10,75,65}},{{6,33,75},{23,104,170},{97,200,243},{209,250,255},{116,223,211},{36,120,178}},{{103,45,145},{216,118,221},{255,173,201},{255,228,238},{164,222,249},{139,141,224}},{{66,32,0},{152,97,0},{229,172,45},{255,219,119},{255,241,179},{191,121,21}},{{22,0,0},{80,2,7},{179,14,23},{250,50,41},{255,118,54},{163,43,16}}};
static inline void strip_palette_sample(unsigned id,double phase,uint8_t rgb[3]){
 if(id>=STRIP_PALETTE_COUNT)id=0;
 if(!isfinite(phase))phase=0;
 double x=(phase-floor(phase))*6.;unsigned i=(unsigned)x;double f=x-i;
 for(unsigned k=0;k<3;k++)rgb[k]=(uint8_t)lround(strip_palette_stops[id][i][k]*(1-f)+strip_palette_stops[id][(i+1)%6][k]*f);
}
